SYMBOL = re.compile(r'(?:rtSym|sym)\(\s*"([^"]+)"')
NAME = re.compile(r"^[%#$&!]?([A-Za-z_][A-Za-z0-9_]*)")


def originals():
    found = {}
    for source in ("blitz3d", "blitzplus_msvc2017"):
        base = os.path.join(ROOT, "third_party", source)
        for directory, _, files in os.walk(base):
            for name in sorted(files):
                if not name.endswith(".cpp") or name not in MODULES:
                    continue
                text = open(os.path.join(directory, name), errors="replace").read()
                # What the original has commented out is not registered, and so does not exist for programs.
                text = re.sub(r"/\*.*?\*/", "", text, flags=re.S)
                text = re.sub(r"^\s*//.*$", "", text, flags=re.M)
                for match in SYMBOL.finditer(text):
                    n = NAME.match(match.group(1))
                    if not n or n.group(1).startswith("_"):
                        continue
                    found.setdefault(n.group(1).lower(), (MODULES[name], match.group(1)))
    for name, entry in EXTENSIONS.items():
        found.setdefault(name, entry)
    return found


def implemented():
    text = open(os.path.join(ROOT, "code_compiler", "source", "builtins.inc")).read()
    return set(re.findall(r'\{\s*"([a-z0-9_]+)"', text)) | BY_COMPILER


def compiler_words():
    """Every word that the compiler sources have in quotes, which is where it handles the functions of BY_COMPILER."""
    words = set()
    directory = os.path.join(ROOT, "code_compiler", "source")
    for name in os.listdir(directory):
        if name.endswith((".cpp", ".hpp")):
            words |= set(re.findall(r'"([a-z0-9_]+)"', open(os.path.join(directory, name), errors="replace").read().lower()))
    return words


def read_list():
    entries = []
    for line in open(LIST):
        line = line.rstrip("\n")
        if line and not line.startswith("#"):
            entries.append(line.split("\t"))
    return entries


def command_list():
    done = implemented()
    rows = []
    for name, (module, signature) in sorted(originals().items(), key=lambda item: (item[1][0], item[0])):
        rows.append((name, module, "done" if name in done else "pending", signature))
    os.makedirs(SUITE, exist_ok=True)
    with open(LIST, "w", newline="\n") as out:
        out.write("# name\tmodule\tstate\tsignature (from the original)\n")
        for row in rows:
            out.write("\t".join(row) + "\n")
    print("%d functions, %d pending" % (len(rows), sum(1 for r in rows if r[2] == "pending")))


def example_arguments(signature):
    """Arguments for a call of the function, made from the signature it was registered with."""
    body = signature[1:] if signature[:1] in "%#$&!" else signature
    body = re.sub(r"^[A-Za-z_][A-Za-z0-9_]*", "", body)
    arguments = []
    for kind, name, default in re.findall(r"([%#$!])([A-Za-z_][A-Za-z0-9_]*)(=[^%#$!]*)?", body):
        if default:
            continue
        arguments.append('""' if kind == "$" else ("1.0" if kind == "#" else "1"))
    return ", ".join(arguments)


def command_pending():
    os.makedirs(PENDING, exist_ok=True)
    for name, module, state, signature in read_list():
        path = os.path.join(PENDING, "%s.bb" % name)
        if state != "pending" or os.path.exists(path):
            continue
        returns = signature[:1] in "%#$&!"
        call = "%s(%s)" % (name, example_arguments(signature)) if returns else "%s %s" % (name, example_arguments(signature))
        with open(path, "w", newline="\n") as out:
            out.write("; AUTOGENERATED COPYRIGHT HEADER START\n")
            out.write("; Copyright (C) 2025 Michael Fabian 'Xaymar' Dirks <info@xaymar.com>\n")
            out.write("; AUTOGENERATED COPYRIGHT HEADER END\n")
            out.write("; %s (%s) is not implemented yet. This fails to compile until it is. Once it is, replace this with a\n" % (name, module))
            out.write("; real test in the module's file, delete this one, and run suite_functions.py list.\n")
            out.write("; Signature of the original: %s\n" % signature)
            out.write(("Local result = %s\n" % call) if returns else ("%s\n" % call))
    print("pending tests written")


def command_check():
    names = open(os.devnull)  # noqa: unused, keeps the structure obvious
    done = implemented()
    text = ""
    for directory, _, files in os.walk(SUITE):
        if directory.startswith(PENDING):
            continue
        for name in files:
            if name.endswith(".bb"):
                text += open(os.path.join(directory, name), errors="replace").read().lower() + "\n"
    words = set(re.findall(r"[a-z_][a-z0-9_]*", text))
    problems = 0
    handled = compiler_words()
    for name in sorted(BY_COMPILER):
        if name not in handled:
            print("%s is listed in BY_COMPILER but the compiler does not handle it" % name)
            problems += 1
    for name, module, state, signature in read_list():
        if state == "done":
            if name not in done:
                print("%s is listed as done but is not implemented" % name)
                problems += 1
            elif name not in words:
                print("%s (%s) has no test" % (name, module))
                problems += 1
            if os.path.exists(os.path.join(PENDING, "%s.bb" % name)):
                print("%s is implemented, so pending/%s.bb should be deleted" % (name, name))
                problems += 1
        else:
            if name in done:
                print("%s is implemented now: write its test and run 'list'" % name)
                problems += 1
            elif not os.path.exists(os.path.join(PENDING, "%s.bb" % name)):
                print("%s is pending and has no placeholder, run 'pending'" % name)
                problems += 1
    print("%d problems" % problems)
    return 1 if problems else 0


if __name__ == "__main__":
    command = sys.argv[1] if len(sys.argv) > 1 else "check"
    if command == "list":
        command_list()
    elif command == "pending":
        command_pending()
    elif command == "check":
        sys.exit(command_check())
    else:
        print(__doc__)
        sys.exit(2)
